function D({registerIndicator:q,sourceValues:w,nulls:j}){q({id:"oa-qrma",name:"Quadratic Regression Moving Average (QRMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:14,min:3,max:1e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"qrma",type:"line",title:"QRMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(d,F){const m=Math.max(3,Math.floor(Number(F.period)||14)),Q=w(d,F.source||"close"),e=m,f=e*(e-1)/2,h=e*(e-1)*(2*e-1)/6,R=f*f,B=e*(e-1)*(2*e-1)*(3*e*e-3*e-1)/30,b=e,g=f,A=h,c=f,r=h,y=R,l=h,o=R,i=B,u=b*(r*i-y*o)-g*(c*i-y*l)+A*(c*o-r*l),C=Number.isFinite(u)&&Math.abs(u)>=1e-20,p=new Array(d.length);for(let t=0;t<d.length;t++)p[t]=Number.isFinite(Q[t])?Q[t]:0;const M=e-1,N=new Array(d.length).fill(NaN);for(let t=0;t<d.length;t++){if(t<m-1||!C){N[t]=p[t];continue}let x=0,n=0,s=0;const E=t-m+1;for(let a=0;a<m;a++){const v=p[E+a];x+=v,n+=a*v,s+=a*a*v}const I=x*(r*i-y*o)-g*(n*i-s*o)+A*(n*o-s*r),P=b*(n*i-s*o)-x*(c*i-y*l)+A*(c*s-n*l),S=b*(r*s-n*o)-g*(c*s-n*l)+x*(c*o-r*l),T=I/u,W=P/u,z=S/u,k=T+W*M+z*M*M;N[t]=Number.isFinite(k)?k:p[t]}return{qrma:j(N)}}})}export{D as default};
